    try:
        data = json.loads(body)
    except ValueError:
        data = None
    if isinstance(data, dict):
        for key, value in data.items():
            if re.search(r"retry[_-]?after|wait", key, re.I) and type(value) in (int, float):
                return value / 1000 if key.lower().endswith("ms") else float(value)
    match = re.search(rb"(\d+(?:\.\d+)?)\s*(?:seconds|second|secs|sec|s)\b", body)
    return float(match.group(1)) if match else None


def request_json(method, path, check, auth=True):
    """Send the request until a 200 response passes check(). Returns (raw_body, parsed), or (None, None) on 404.

    401/403 fetch a new token and retry. A wait the server states is obeyed. Anything else backs off
    and sends the same request again; nothing is skipped.
    """
    auth_failures = other_failures = rate_waits = 0
    while True:
        if auth and token is None:
            refresh_token()
        status, headers, body = send(method, path, auth)
        if status == 200:
            try:
                data = json.loads(body)
            except ValueError:
                data = None
            if data is not None and check(data):
                return body, data
            problem = f"200 with an unusable body: {body[:200]!r}"
        elif status == 404:
            return None, None
        else:
            problem = f"HTTP {status}: {body[:200]!r}"
        log(f"{method} {path} -> {problem}")
        wait = stated_wait(headers, body) if status is not None else None
        if status in (401, 403):
            auth_failures += 1
            if auth_failures > 5:
                raise RuntimeError(f"{method} {path}: still {status} after {auth_failures} token refreshes")
            refresh_token()
        elif wait is not None:
            rate_waits += 1
            if rate_waits > 200:
                raise RuntimeError(f"{method} {path}: still being told to wait after {rate_waits} tries")
            log(f"  waiting {wait}s as the server asked")
            time.sleep(wait + 0.25)
        elif status == 429:
            raise RuntimeError(f"{method} {path}: 429 with no wait I can read; headers={dict(headers)}")
        else:
            other_failures += 1
            if other_failures > 12:
                raise RuntimeError(f"{method} {path}: still failing after {other_failures} attempts")
            time.sleep(min(30, 0.5 * 2 ** other_failures))


def refresh_token():
    global token
    _, data = request_json("POST", "/token", lambda d: isinstance(d, dict) and "token" in d, auth=False)
    if data is None:
        raise RuntimeError("POST /token returned 404")
    token = data["token"]
    log("token refreshed")


def write_atomic(path, body):
    with open(path + ".tmp", "wb") as f:
        f.write(body)
    os.replace(path + ".tmp", path)


def read_cached(path):
    with open(path, "rb") as f:
        return json.loads(f.read())


def check_page(number):
    def check(data):
        if not (isinstance(data, dict) and data.get("page") == number and isinstance(data.get("items"), list)
                and isinstance(data.get("total_pages"), int) and "next" in data):
            return False
        count = len(data["items"])
        if number == data["total_pages"]:  # last page
            return 1 <= count <= PAGE_SIZE
        return count == PAGE_SIZE
    return check


def fetch_page(number):
    cache = os.path.join(RAW_DIR, f"orders-page-{number:03d}.json")
    if os.path.exists(cache):
        return read_cached(cache)
    body, data = request_json("GET", f"/orders?page={number}", check_page(number))
    if data is None:
        raise RuntimeError(f"orders page {number} returned 404")
    write_atomic(cache, body)
    return data


def fetch_orders():
    pages = []
    total = None
    number = 1
    while total is None or number <= total:
        data = fetch_page(number)
        if total is None:
            total = data["total_pages"]
        elif data["total_pages"] != total:
            raise RuntimeError(f"total_pages changed from {total} to {data['total_pages']} on page {number}")
        expected_next = f"/orders?page={number + 1}" if number < total else None
        if data["next"] != expected_next:
            raise RuntimeError(f"page {number}: next is {data['next']!r}, expected {expected_next!r}")
        log(f"page {number}/{total}: {len(data['items'])} listings")
        pages.append(data)
        number += 1
    return pages


def check_customer(cid):
    def check(data):
        return isinstance(data, dict) and data.get("id") == cid and "region" in data and "discount_pct" in data
    return check


def fetch_customer(cid):
    cache = os.path.join(RAW_DIR, f"customer-{cid}.json")
    if os.path.exists(cache):
        return read_cached(cache)
    for _ in range(2):  # a 404 is repeated once before it is believed
        body, data = request_json("GET", f"/customers/{cid}", check_customer(cid))
        if data is not None:
            write_atomic(cache, body)
            return data
    return None


def to_utc(placed_at):
    return datetime.fromisoformat(placed_at.replace("Z", "+00:00")).astimezone(timezone.utc)


def offset_of(placed_at):
    return re.search(r"(Z|[+-]\d{2}:\d{2})$", placed_at).group(1)


def discounted_cents(amount_cents, discount_pct):
    """The order's amount less discount_pct percent, rounded half up to a whole cent for this order alone."""
    exact = Decimal(amount_cents) * (100 - discount_pct) / 100
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def well_formed(item):
    return (isinstance(item, dict)
            and all(isinstance(item.get(k), str) for k in ("id", "customer_id", "status", "placed_at"))
            and type(item.get("amount_cents")) is int
            and TIMESTAMP.fullmatch(item["placed_at"]) is not None)


def main():
    pages = fetch_orders()
    listed = [item for page in pages for item in page["items"]]
    log(f"{len(pages)} pages, {len(listed)} listings in total")

    malformed = [item for item in listed if not well_formed(item)]
    if malformed:
        raise RuntimeError(f"{len(malformed)} malformed listings; first few: {malformed[:3]}")

    distinct = {}
    dups = Counter()
    conflicts = []
    for item in listed:
        oid = item["id"]
        if oid not in distinct:
            distinct[oid] = item
        else:
            dups[oid] += 1
            if distinct[oid] != item:
                conflicts.append((distinct[oid], item))
    log(f"{len(distinct)} distinct orders; {sum(dups.values())} repeated listings across {len(dups)} ids")
    if conflicts:
        raise RuntimeError(f"{len(conflicts)} repeated ids disagree with their first listing; first: {conflicts[0]}")

    orders = list(distinct.values())
    ids = sorted(distinct)
    odd = [oid for oid in ids if not re.fullmatch(r"ord-\d{4}", oid)]
    nums = {int(oid[4:]) for oid in ids if oid not in odd}
    gaps = sorted(set(range(1, max(nums) + 1)) - nums)
    log(f"ids {ids[0]}..{ids[-1]}; unusual ids: {odd[:10]}; gaps in numbering: {len(gaps)} {gaps[:20]}")
    log(f"statuses: {dict(Counter(o['status'] for o in orders))}")
    log(f"offsets: {dict(Counter(offset_of(o['placed_at']) for o in orders))}; "
        f"with fractional seconds: {sum('.' in o['placed_at'] for o in orders)}")

    in_range = [o for o in orders if RANGE_START <= to_utc(o["placed_at"]) < RANGE_END]
    qualifying = [o for o in in_range if o["status"] == "shipped"]
    by_written_date = [o for o in orders
                       if o["status"] == "shipped" and "2025-03-01" <= o["placed_at"][:10] <= "2025-05-31"]
    log(f"in range in UTC: {len(in_range)} orders; shipped and in range: {len(qualifying)}")
    log(f"for comparison, shipped orders whose written date is in range: {len(by_written_date)}")

    customer_ids = sorted({o["customer_id"] for o in qualifying})
    customers = {cid: fetch_customer(cid) for cid in customer_ids}
    missing = [cid for cid, c in customers.items() if c is None]
    if missing:
        raise RuntimeError(f"customers not found: {missing}")
    for cid, c in customers.items():
        if c["region"] not in REGIONS or type(c["discount_pct"]) is not int or not 0 <= c["discount_pct"] <= 100:
            raise RuntimeError(f"unexpected customer record {cid}: {c}")
    log(f"{len(customer_ids)} customers looked up")

    by_region = {region: 0 for region in REGIONS}
    for o in qualifying:
        c = customers[o["customer_id"]]
        by_region[c["region"]] += discounted_cents(o["amount_cents"], c["discount_pct"])
    result = {
        "total_cents": sum(by_region.values()),
        "order_count": len(qualifying),
        "duplicates_skipped": sum(dups.values()),
        "by_region": by_region,
    }
    log(json.dumps(result))
    with open(OUT_PATH, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")
    log(f"wrote {OUT_PATH}")


if __name__ == "__main__":
    main()
